/**
 * @name Dynamic attribute access with tainted input
 * @description Using getattr/setattr with user-controlled attribute names can lead to unauthorized access
 * @kind path-problem
 * @problem.severity warning
 * @id py/tainted-attribute-access-six
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module TaintedAttributeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asCfgNode().(NameNode).getId() in ["getattr", "setattr", "delattr", "hasattr"] and
      sink = call.getArg(1)
    )
  }
}

module TaintedAttributeFlow = TaintTracking::Global<TaintedAttributeConfig>;
import TaintedAttributeFlow::PathGraph

from TaintedAttributeFlow::PathNode source, TaintedAttributeFlow::PathNode sink
where TaintedAttributeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic attribute access with user-controlled name from $@.", source.getNode(), "user input"
